// Read-only diagnostic of existing live DP4 identity metadata and species links.
// Exact-language matches flag review; they do not authorize canonical mutations.
import fs from 'node:fs';import {gunzipSync} from 'node:zlib';import crypto from 'node:crypto';import assert from 'node:assert/strict';
const dir='docs/audits/jpn_dp4_artist_review_20261119',read=n=>fs.readFileSync(`${dir}/${n}`),snapshot=JSON.parse(read('live-identity-species-20261119.json')),pairs=JSON.parse(read('species_name_pairs.json')),index=JSON.parse(read('species_name_source_index.json'));assert.equal(snapshot.sanity.read_only,'on');assert.equal(snapshot.current.length,136);for(const entry of index){const source=JSON.parse(gunzipSync(read(entry.file)));assert.equal(source.status,200);assert.equal(crypto.createHash('sha256').update(source.body_text).digest('hex'),entry.body_sha256);assert.equal(source.body_sha256,entry.body_sha256)}const names=JSON.parse(gunzipSync(read('species_name_sources/pokemon_species_names.csv.json.gz'))).body_text.split(/\r?\n/).map(x=>x.split(','));
const parent=new Map(snapshot.current.map(p=>[p.id,p])),norm=s=>s.normalize('NFKD').toLowerCase().replace(/[^a-z0-9]+/g,''),identity=[],species=[];const expected=p=>{const x=pairs.filter(v=>v.ja===p.name);if(x.length!==1)return null;const q=x[0];assert.ok(names.some(r=>r[0]===q.species_id&&r[1]==='9'&&r[2]===q.en));assert.ok(names.some(r=>r[0]===q.species_id&&['1','11'].includes(r[1])&&r[2]===q.ja));return q};
for(const row of snapshot.identities){const i=row.identity,p=parent.get(i.card_print_id),q=p&&expected(p);if(!q||!i.is_active)continue;const values=i.identity_payload?.card_name_en_candidates??[];assert.ok(Array.isArray(values));const match=values.some(v=>typeof v==='string'&&norm(v.split(' (')[0])===norm(q.en));identity.push({gv_id:p.gv_id,japanese_name:p.name,expected_english:q.en,expected_dex:q.species_id,existing_english_candidates:values,match});}
for(const row of snapshot.species){const l=row.link,p=parent.get(l.card_print_id),q=p&&expected(p);if(!q||!l.active||!row.species)continue;species.push({gv_id:p.gv_id,japanese_name:p.name,expected_english:q.en,expected_dex:Number(q.species_id),actual_species:row.species.canonical_name,actual_dex:row.species.national_dex_number,role:l.role,match:Number(q.species_id)===row.species.national_dex_number});}
const out={version:'JPN_DP4_LIVE_IDENTITY_DIAGNOSTIC_V1',generated_at:new Date().toISOString(),scope:'Heuristic exact Japanese species-name comparison using a retained source snapshot. Disagreements are review flags, not independently adjudicated repairs.',readback_captured_at:snapshot.captured_at,parents:snapshot.current.length,identity_compared:identity.length,identity_mismatches:identity.filter(x=>!x.match).length,species_compared:species.length,species_mismatches:species.filter(x=>!x.match).length,identity,species};if(!process.argv.includes('--check'))fs.writeFileSync(`${dir}/live-identity-species-diagnostic-20261119.json`,JSON.stringify(out,null,2)+'\n',{flag:'wx'});console.log(JSON.stringify({parents:out.parents,identity_compared:out.identity_compared,identity_mismatches:out.identity_mismatches,species_compared:out.species_compared,species_mismatches:out.species_mismatches}));
